//! Golden expectations generated by the unchanged Python revenue module.
use concierge_core::revenue::{self, Period};
use serde_json::Value;

#[test]
fn revenue_matches_python_arithmetic_and_report_shapes() {
    let cases: Value =
        serde_json::from_str(include_str!("../parity/revenue_vectors.json")).unwrap();
    for case in cases["arithmetic"].as_array().unwrap() {
        let (a, b) = (case["a"].as_i64().unwrap(), case["b"].as_i64().unwrap());
        assert_eq!(
            serde_json::to_value(revenue::percent_change(a, b)).unwrap(),
            case["change"],
            "change {a}/{b}"
        );
        assert_eq!(
            revenue::per_enquiry(a, b),
            case["average"].as_i64().unwrap(),
            "average {a}/{b}"
        );
        assert_eq!(
            revenue::convert_rate(a, b),
            case["rate"].as_f64().unwrap(),
            "rate {a}/{b}"
        );
    }
    for case in cases["build"].as_array().unwrap() {
        let current: Period = serde_json::from_value(case["current"].clone()).unwrap();
        let previous: Period = serde_json::from_value(case["previous"].clone()).unwrap();
        assert_eq!(revenue::build(&current, &previous), case["expected"]);
    }
}

#[test]
fn report_window_preserves_python_default_and_limits() {
    for (input, expected) in [
        (0, 30),
        (-1, 1),
        (1, 1),
        (30, 30),
        (365, 365),
        (366, 365),
        (i64::MAX, 365),
        (i64::MIN, 1),
    ] {
        assert_eq!(revenue::clamp_days(input.into()), expected);
    }
}
